function renderSearchErrorState(result: CommitData, isPending = false) {
  const onRetry = vi.fn();
  const errorState = (pending: boolean) => (
    <SearchErrorState
      result={result}
      exampleUsernames={["octocat"]}
      isPending={pending}
      lastSearchedUsername="octo"
      onRetry={onRetry}
      onReset={() => {}}
      onExampleSearch={() => {}}
