const recentSearchTimes = new Map<string, number[]>();

function dropIdleClients(now: number) {
  const windowStart = now - COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS;

  for (const [clientKey, searchTimes] of recentSearchTimes) {
